    # Since Frobenius number is 189, we only need to check up to 189.
    # But wait, the Frobenius number is the largest integer NOT in G.
    # Let's compute all integers up to some limit and see.
    limit = 11 * 20 = 220
    G = set()
    for a in range(limit):
        for b in range(limit):
            val = 11 * a + 20 * b
            if val < limit:
                G.add(val)
            else:
                break

    # Actually, we just need to find all n < 189 that are not in G.
    A = []
    for n in range(220):
        if n not in G:
            A.append(n)
    return A, G

