def find_max_antichain(A, reach):
    import itertools
    # This is a bit slow for 95. Let's use Dilworth's Theorem.
    # The width of a poset is the minimum number of chains to cover all elements.
    # This can be solved using maximum bipartite matching.
    n = len(A)
    # Bipartite graph with 2n nodes.
    # Edge from (u, left) to (v, right) if u -> v in the poset and u != v.
    match = [-1] * n
    adj_match = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and A[j] in reach[A[i]]:
                adj_match[i].append(j)

    def can_match(u, visited):
        for v in adj_match[u]:
            if not visited[v]:
                visited[v] = True
                if match[v] < 0 or can_match(match[v], visited):
                    match[v] = u
                    return True
        return False

    matching_size = 0
    for i in range(n):
        visited = [False] * n
        if can_match(i, visited):
            matching_size += 1

    return n - matching_size

