def solve():
    a, b = 11, 20
    M = set()
    for i in range(200):
        for j in range(20):
            M.add(i * a + j * b)

    R = [i for i in range(200) if i not in M]
    R.sort()
    n = len(R)

    poset = [[] for _ in range(n)]
    for i, r in enumerate(R):
        if r - a >= 0 and (r - a) in R:
            poset[i].append(R.index(r - a))
        if r - b >= 0 and (r - b) in R:
            poset[i].append(R.index(r - b))

    max_dist = 0
    for i, r in enumerate(R):
        for pred_idx in poset[i]:
            max_dist = max(max_dist, i - pred_idx)

    # dp[mask] is the number of downsets of the first i elements
    # where mask represents the status of {r_{i-max_dist}, ..., r_{i-1}}.
    # The mask is a bitmask where the j-th bit (from the right) is the status of r_{i-max_dist+j}.
    # No, it's easier to use: the j-th bit is the status of r_{i-1-j}.
    # So the bit at position 0 is r_{i-1}, bit 1 is r_{i-2}, ..., bit max_dist-1 is r_{i-max_dist}.

    dp = {0: 1}

    for i in range(n):
        new_dp = {}
        for mask, count in dp.items():
            # Option 1: r_i is NOT in the downset (x_i = 0)
            # The new mask will be (mask << 1) & ((1 << max_dist) - 1)
            new_mask_0 = (mask << 1) & ((1 << max_dist) - 1)
            new_dp[new_mask_0] = new_dp.get(new_mask_0, 0) + count

            # Option 2: r_i IS in the downset (x_i = 1)
            # This is allowed only if all predecessors of r_i are in the downset.
            # Predecessors are r_i-11 and r_i-20.
            # Their indices are in poset[i].
            # The status of r_j (j < i) is bit (i-1-j) of the mask.

            allowed = True
            for pred_idx in poset[i]:
                # The status of r_{pred_idx} is the (i-1-pred_idx)-th bit.
                bit_pos = i - 1 - pred_idx
                if not (mask & (1 << bit_pos)):
                    allowed = False
                    break

            if allowed:
                new_mask_1 = ((mask << 1) | 1) & ((1 << max_dist) - 1)
                new_dp[new_mask_1] = new_dp.get(new_mask_1, 0) + count
        dp = new_dp

    print(f"Total downsets: {sum(dp.values())}")

solve()

