    def backtrack(idx, current_clique_mask):
        nonlocal count
        for i in range(idx, n):
            if (adj[i] & current_clique_mask) == current_clique_mask:
                count += 1
                backtrack(i + 1, current_clique_mask | (1 << i))
    backtrack(0, 0)
    return count

