def solve():
    limit = 300
    B = set()
    for a in range(limit // 11 + 1):
        for b in range(limit // 20 + 1):
            B.add(11 * a + 20 * b)

    U = [n for n in range(200) if n not in B]
    U.sort()
    u_to_idx = {val: i for i, val in enumerate(U)}
    n_u = len(U)

    adj = [[] for _ in range(n_u)]
    for i, x in enumerate(U):
        for step in [11, 20]:
            y = x + step
            if y in u_to_idx:
                adj[i].append(u_to_idx[y])

    G = nx.DiGraph()
    for i in range(n_u):
        for j in adj[i]:
            G.add_edge(i, j)

    # Find width (max antichain size)
    # For a DAG, width = n - max matching in the bipartite version.
    # The bipartite version has edges (u, v) if there is a path from u to v.
    # Wait, the width of a poset is the max antichain. 
    # The width of a DAG is the max antichain of its reachability relation.

    # Step 1: Reachability
    reach = nx.transitive_closure(G)

    # Step 2: Max matching in the reachability graph's bipartite version
    # To find max antichain size:
    # Build a bipartite graph with 2*n_u nodes.
    # For each u, v such that u can reach v and u != v, add edge (u_left, v_right).
    # Max antichain size = n_u - max_matching.

    bipartite_adj = [[] for _ in range(n_u)]
    for u in range(n_u):
        for v in range(n_u):
            if u != v and reach[u][v]:
                bipartite_adj[u].append(v)

    match = [-1] * n_u
    def dfs(u, visited):
        for v in bipartite_adj[u]:
            if not visited[v]:
                visited[v] = True
                if match[v] < 0 or dfs(match[v], visited):
                    match[v] = u
                    return True
        return False

    matching_size = 0
    for i in range(n_u):
        visited = [False] * n_u
        if dfs(i, visited):
            matching_size += 1

    width = n_u - matching_size
    print(f"Width: {width}")

